const input = $input.first().json;
const isChat = Object.prototype.hasOwnProperty.call(input, 'chatInput');
const payload = isChat ? input : (input.body ?? input);
const message = String(isChat ? input.chatInput : (payload.message ?? payload.summary ?? payload.description ?? '')).trim();
const sourceEventId = String(payload.source_event_id ?? payload.event_id ?? '').trim();
const accountId = String(payload.account_id ?? '').trim();
const companyName = String(payload.company_name ?? payload.account_name ?? '').trim();
const requester = String(payload.requester ?? payload.requester_email ?? payload.user ?? '').trim();
const suppliedCaseId = String(payload.case_id ?? '').trim();

function stableHash(value) {
  let h1 = 0xdeadbeef ^ value.length;
  let h2 = 0x41c6ce57 ^ value.length;
  for (let i = 0; i < value.length; i++) {
    const ch = value.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
}

const idMaterial = sourceEventId || [accountId, companyName.toLowerCase(), message.toLowerCase()].join('|');
const caseId = suppliedCaseId || `case_${stableHash(idMaterial)}`;
const errors = [];
if (!message) errors.push('message is required');
if (!caseId) errors.push('case_id could not be generated');

return [{json:{
  trigger_type: isChat ? 'chat' : 'webhook',
  case_id: caseId,
  source_event_id: sourceEventId,
  account_id_hint: accountId,
  company_name_hint: companyName,
  requester,
  message,
  received_at: new Date().toISOString(),
  is_valid: errors.length === 0,
  validation_errors: errors,
  raw_metadata: payload.metadata ?? {}
}}];

const normalized = $('Normalize and validate input').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.case_id);
const cached = rows.find(r => ['completed','human_approval_required','awaiting_approval','needs_clarification'].includes(String(r.status))) ?? null;
return [{json:{...normalized,is_duplicate:Boolean(cached),cached_case:cached}}];

const c = $json.cached_case;
return [{json:{
  output: c.customer_draft || 'This case already exists and is awaiting review.',
  case_id: c.case_id,
  status: c.status,
  severity: c.severity,
  confidence: Number(c.confidence || 0),
  approval_reason: c.approval_reason || '',
  cached: true
}}];

