const state = $('Parse investigation JSON').first().json;
const raw = $input.first().json.text ?? $input.first().json.output ?? '';
try {
  const cleaned = typeof raw === 'string' ? raw.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim() : raw;
  const draft = typeof cleaned === 'object' ? cleaned : JSON.parse(cleaned);
  if (!draft.internal_plan || !draft.customer_draft) throw new Error('missing required draft fields');
  return [{json:{...state,draft,draft_valid:true}}];
} catch (error) {
  return [{json:{...state,draft:{internal_plan:'Manual review required because the response writer returned invalid output.',customer_draft:'We are reviewing your report and will follow up after validating the relevant account and system details.',commitments:[],claims_used:[]},draft_valid:false,draft_error:error.message}}];
}

parameters.text:
=You are the RISK REVIEWER role. Review the draft against the evidence and policy constraints.
Flag unsupported claims, disclosure of other customers, promises of refunds/fix dates, missing owners, or claims stronger than the evidence.
Return ONLY JSON:
{"approved":true,"safe_to_send":true,"material_issues":["string"],"unsupported_claims":["string"],"required_changes":["string"],"approval_reason":"string"}
approved and safe_to_send may be true only if there are no material issues.

INVESTIGATION:
{{ JSON.stringify($json.investigation) }}
DRAFT:
{{ JSON.stringify($json.draft) }}

parameters.jsCode:
const state = $('Parse draft JSON').first().json;
const raw = $input.first().json.text ?? $input.first().json.output ?? '';
let review;
let reviewValid = true;
try {
  const cleaned = typeof raw === 'string' ? raw.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim() : raw;
  review = typeof cleaned === 'object' ? cleaned : JSON.parse(cleaned);
} catch (error) {
  reviewValid = false;
  review = {approved:false,safe_to_send:false,material_issues:['Risk review returned invalid structured output'],unsupported_claims:[],required_changes:['Perform manual review'],approval_reason:error.message};
}
const renewalDate = state.account.renewal_date ? new Date(state.account.renewal_date) : null;
const daysToRenewal = renewalDate && !Number.isNaN(renewalDate.valueOf()) ? Math.ceil((renewalDate - new Date()) / 86400000) : null;
const renewalCritical = daysToRenewal !== null && daysToRenewal >= 0 && daysToRenewal <= 30;
const confidence = Math.min(Number(state.triage.confidence || 0),Number(state.investigation.confidence || 0));
const structuralFailure = !state.triage_valid || !state.investigation_valid || !state.draft_valid || !reviewValid;
const approvalRequired = structuralFailure || ['high','critical'].includes(state.triage.severity) || confidence < 0.7 || renewalCritical || !review.safe_to_send;
const reasons = [];
if (structuralFailure) reasons.push('One or more AI stages failed structured validation');
if (['high','critical'].includes(state.triage.severity)) reasons.push(`Severity is ${state.triage.severity}`);
if (confidence < 0.7) reasons.push(`Evidence confidence is ${confidence.toFixed(2)}`);
if (renewalCritical) reasons.push(`Renewal is within ${daysToRenewal} days`);
if (!review.safe_to_send) reasons.push(review.approval_reason || 'Risk reviewer did not mark the draft safe');
return [{json:{...state,review,review_valid:reviewValid,confidence,days_to_renewal:daysToRenewal,approval_required:approvalRequired,approval_reasons:reasons,revision_needed:Array.isArray(review.required_changes) && review.required_changes.length > 0}}];

