const state = $('Parse review and decide').first().json;
const raw = $input.first().json.text ?? $input.first().json.output ?? '';
try {
  const cleaned = typeof raw === 'string' ? raw.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim() : raw;
  const finalDraft = typeof cleaned === 'object' ? cleaned : JSON.parse(cleaned);
  if (!finalDraft.internal_plan || !finalDraft.customer_draft) throw new Error('missing required revised fields');
  return [{json:{...state,final_draft:finalDraft,revision_valid:true}}];
} catch (error) {
  return [{json:{...state,final_draft:state.draft,revision_valid:false,approval_required:true,approval_reasons:[...state.approval_reasons,'Revision output failed validation'],revision_error:error.message}}];
}

const s = $json;
const now = new Date().toISOString();
const evidenceRecord = {
  triage:s.triage,
  investigation:s.investigation,
  review:s.review,
  sources:s.evidence,
  model_stage_validation:{triage:s.triage_valid,investigation:s.investigation_valid,draft:s.draft_valid,review:s.review_valid,revision:s.revision_valid},
  retrieved_at:s.evidence.retrieved_at
};
return [{json:{
  case_id:s.case_id,
  source_event_id:s.source_event_id,
  account_id:s.account.account_id,
  status:s.approval_required ? 'human_approval_required' : 'completed',
  severity:s.triage.severity,
  confidence:String(s.confidence),
  evidence_json:JSON.stringify(evidenceRecord),
  internal_plan:s.final_draft.internal_plan,
  customer_draft:s.final_draft.customer_draft,
  approval_reason:s.approval_reasons.join('; '),
  created_at:s.received_at,
  updated_at:now,
  approval_required:s.approval_required
}}];

const c = $('Prepare auditable case row').first().json;
return [{json:{
  output:`A draft has been prepared, but human approval is required before it can be used.

Reason: ${c.approval_reason}

Customer-safe draft:
${c.customer_draft}`,
  case_id:c.case_id,status:c.status,severity:c.severity,confidence:Number(c.confidence),approval_reason:c.approval_reason
}}];
